49	    // check shape length is DIM_SIZE
50	    OP_CHECK_IF(
51	        shapePtr->GetStorageShape().GetDimNum() != DIM_SIZE, OP_LOGE(context, "Shape must be (B,N,S,D)."),
52	        return std::make_tuple(0, 0, 0, 0));
