89	bool AiInfraKvRmsNormRopeCacheTilingBase::CheckVValid(
90	    const gert::TilingContext* context, int64_t batchSize, int64_t numHead, int64_t seqLen, int64_t headSize)
91	{
92	    auto vShapeTuple = GetOptionalShapeTuple(context, V_IDX);
93	    bool isValid = true;
94	    isValid = isValid && (std::get<SHAPE_IDX_B>(vShapeTuple) == batchSize);
95	    isValid = isValid && (std::get<SHAPE_IDX_N>(vShapeTuple) == numHead);
96	    isValid = isValid && (std::get<SHAPE_IDX_S>(vShapeTuple) == seqLen);
97	    isValid = isValid && (std::get<SHAPE_IDX_D>(vShapeTuple) == headSize);
98	
99	    return isValid;
100	}
101	
102	bool AiInfraKvRmsNormRopeCacheTilingBase::CheckCosSinValid(
103	    const gert::TilingContext* context, int64_t batchSize, int64_t numHead, int64_t seqLen, int64_t headSize)
104	{
105	    auto cosShapeTuple = GetShapeTuple(context, COS_INDEX);
106	    auto sinShapeTuple = GetShapeTuple(context, SIN_INDEX);
107	    bool isValid = true;
108	    isValid = isValid && (std::get<SHAPE_IDX_B>(cosShapeTuple) == batchSize);
109	    isValid = isValid && (std::get<SHAPE_IDX_N>(cosShapeTuple) == numHead);
110	    isValid = isValid && (std::get<SHAPE_IDX_D>(cosShapeTuple) == headSize);
111	    isValid = isValid && (std::get<SHAPE_IDX_B>(sinShapeTuple) == batchSize);
112	    isValid = isValid && (std::get<SHAPE_IDX_N>(sinShapeTuple) == numHead);
113	    isValid = isValid && (std::get<SHAPE_IDX_D>(sinShapeTuple) == headSize);
114	    auto cosSeq = std::get<SHAPE_IDX_S>(cosShapeTuple);
115	    auto sinSeq = std::get<SHAPE_IDX_S>(sinShapeTuple);
116	    isValid = isValid && (cosSeq == sinSeq);
117	    if ((cosSeq != seqLen)) {
118	        if (cosSeq == 1) {
119	            cosSinNeedBrc_ = 1;
120	        } else {
121	            return false;
122	        }
123	    }
124	    this->ropeSeqLength = static_cast<int64_t>(cosSeq);
125	
126	    if (currentCacheMode_ == CacheMode::PA_BLK_NZ || currentCacheMode_ == CacheMode::PA_NZ) {
127	        auto kcacheDesc = context_->GetInputDesc(K_CACHE_INDEX);
128	        OP_CHECK_NULL_WITH_CONTEXT(context_, kcacheDesc);
129	        ge::DataType kcacheDtype = kcacheDesc->GetDataType();
130	        if (kcacheDtype == ge::DT_INT8) {
131	            isValid = isValid && (std::get<SHAPE_IDX_D>(sinShapeTuple) % INT8_BLOCK_ALIGN_NUM == 0);
132	        } else {
133	            isValid = isValid && (std::get<SHAPE_IDX_D>(sinShapeTuple) % FP16_BLOCK_ALIGN_NUM == 0);
134	        }
135	    }
136	    return isValid;
137	}
