139	bool AiInfraKvRmsNormRopeCacheTilingBase::CheckGammaValid(const gert::TilingContext* context, int64_t headSize)
140	{
141	    const gert::StorageShape* gammaShapePtr = context->GetInputShape(GAMMA_INDEX);
142	    bool isValid = true;
143	    isValid = isValid && (gammaShapePtr != nullptr);
144	    isValid = isValid && (gammaShapePtr->GetStorageShape().GetDimNum() == 1);
145	    isValid = isValid && (gammaShapePtr->GetStorageShape().GetDim(0) == headSize);
146	
147	    if (currentCacheMode_ == CacheMode::PA_BLK_NZ || currentCacheMode_ == CacheMode::PA_NZ) {
148	        auto vcacheDesc = context_->GetInputDesc(V_CACHE_INDEX);
149	        OP_CHECK_NULL_WITH_CONTEXT(context_, vcacheDesc);
150	        ge::DataType vcacheDtype = vcacheDesc->GetDataType();
151	        if (vcacheDtype == ge::DT_INT8) {
152	            isValid = isValid && (gammaShapePtr->GetStorageShape().GetDim(0) % INT8_BLOCK_ALIGN_NUM == 0);
153	        } else {
154	            isValid = isValid && (gammaShapePtr->GetStorageShape().GetDim(0) % FP16_BLOCK_ALIGN_NUM == 0);
155	        }
156	    }
157	    return isValid;
158	}
159	
160	bool AiInfraKvRmsNormRopeCacheTilingBase::CheckIndexValid(
161	    const gert::TilingContext* context, int64_t batchSize, int64_t seqLen, int64_t pageSize, CacheMode mode)
162	{
163	    bool isValid = true;
164	    const gert::StorageShape* indexShapePtr = context->GetInputShape(INDEX_INDEX);
165	    isValid = isValid && (indexShapePtr != nullptr);
166	    OP_CHECK_IF(!isValid, OP_LOGE(context, "Index shape pointer is null."), return false);
167	    auto shapeSize = indexShapePtr->GetStorageShape().GetShapeSize();
168	    if (mode == CacheMode::NORM || mode == CacheMode::PA || mode == CacheMode::PA_NZ) {
169	        isValid = isValid && (shapeSize == batchSize * seqLen);
170	        OP_CHECK_IF(!isValid, OP_LOGE(context, "Index's shape size must equal with B*S."), return false);
171	    } else {
172	        OP_CHECK_IF(pageSize < DIM_NUM_ONE, OP_LOGE(context, "pageSize MUST BE POSITIVE Integer!"), return false);
173	
174	        int64_t page_num = (seqLen + pageSize - 1) / pageSize;
175	        isValid = isValid && (shapeSize == batchSize * page_num);
176	
177	        OP_CHECK_IF(
178	            !isValid, OP_LOGE(context, "Index's shape size must equal with batchSize * page_num."), return false);
179	    }
180	    return isValid;
181	}
182	
183	int64_t AiInfraKvRmsNormRopeCacheTilingBase::GetComponentStaticQuantMode(
184	    const gert::TilingContext* context, int64_t qScaleIdx, int64_t qOffsetIdx)
185	{
186	    auto scaleShape = context->GetOptionalInputShape(qScaleIdx);
187	    if (scaleShape == nullptr) {
188	        return NON_QUANT_MODE; // NONE Quant
189	    } else {
190	        if (this->methodMode_ == DIM_ONE) {
191	            // V2 Expansion: support Asymmetric Quant
192	            auto offsetShape = context->GetOptionalInputShape(qOffsetIdx);
193	            if (offsetShape) {
194	                return ASYM_QUANT_MODE; // STATIC Asymmetric
195	            }
196	        }
197	        return QUANT_MODE; // STATIC Symmetric
198	    }
199	}
