/*!
 * \file ai_infra_rope_rotate_half_tiling.h
 * \brief
 */
#ifndef AI_INFRA_ROPE_ROTATE_HALF_TILING_H
#define AI_INFRA_ROPE_ROTATE_HALF_TILING_H
#include "register/op_def_registry.h"
#include "ai_infra_rotary_position_embedding_tiling.h"

namespace optiling {

class AiInfraRopeRotateHalfTilingClass : public AiInfraRotaryPosEmbeddingMembaseTilingClass {
public:
    explicit AiInfraRopeRotateHalfTilingClass(gert::TilingContext *context)
        : AiInfraRotaryPosEmbeddingMembaseTilingClass(context)
    {}

protected:
    std::set<platform_ascendc::SocVersion> half_valid_soc = {
        platform_ascendc::SocVersion::ASCEND910B, platform_ascendc::SocVersion::ASCEND910_93};

    bool IsCapable() override
    {
        if (inputMode_ != MODE_ROTATE_INTERLEAVED) {
            return (half_valid_soc.find(socVersion_) != half_valid_soc.end());
        }
        return false;
    }
    // 3、计算数据切分TilingData
    ge::graphStatus DoOpTiling() override;
};

