643	    template <typename T, int64_t D1, int64_t D0>
644	    __aicore__ inline void ScatterUpdatePANZ(
645	        const GlobalTensor<T>& dst, const GlobalTensor<T>& dstNd, const LocalTensor<T>& outLocal, int64_t startIdx,
646	        int64_t rows, int64_t headSize)
647	    {
648	        DataCopyExtParams copyParamsNz{
649	            static_cast<uint16_t>(D1), static_cast<uint32_t>(D0 * sizeof(T)), 0,
650	            static_cast<uint32_t>(this->tilingData_->blockSize * D0 * sizeof(T)) -
651	                static_cast<uint32_t>(D0 * sizeof(T)),
652	            0};
653	        DataCopyExtParams copyParamsNd{1, static_cast<uint32_t>(headSize * sizeof(T)), 0, 0, 0};
654	        int64_t pageIdOffset = D1 * this->tilingData_->blockSize * D0 * this->tilingData_->numHead;
655	        for (int64_t i = 0; i < rows; i++) {
656	            int64_t tokenId = startIdx + i;
657	            int64_t ubOffset = headSize * i;
658	            if (this->tilingData_->isOutputKv) {
659	                int64_t gmOffsetNd = tokenId * headSize;
660	                DataCopyPad(dstNd[gmOffsetNd], outLocal[ubOffset], copyParamsNd);
661	            }
662	
663	            // Index: (B*S,)
664	            // Cache: (bn, bs, N, D) -> (bn, N, D1, bs, D0) N>1
665	            int64_t tokensPerBatch = this->tilingData_->seqLength * this->tilingData_->numHead;
666	            int64_t batchId = tokenId / tokensPerBatch;
667	            int64_t tokenInBatch = tokenId % tokensPerBatch;               // token in batch
668	            int64_t headIdx = tokenInBatch / this->tilingData_->seqLength; // numHead
669	            int64_t seqIdx = tokenInBatch % this->tilingData_->seqLength;  // seq
670	
671	            int64_t pageOffset = this->indexGm(batchId * this->tilingData_->seqLength + seqIdx); // [batch, seq]
672	            int64_t pageId = pageOffset / this->tilingData_->blockSize;
673	            int64_t tokenOffsetInCurrentPage = pageOffset % this->tilingData_->blockSize;
674	            if (pageOffset >= 0) {
675	                int64_t gmOffsetNz = pageId * pageIdOffset +                            // begin
676	                                     headIdx * D1 * this->tilingData_->blockSize * D0 + // head
677	                                     tokenOffsetInCurrentPage * D0;                     // token
678	                SToMTE3Sync();
679	                DataCopyPad(dst[gmOffsetNz], outLocal[ubOffset], copyParamsNz);
680	            }
681	        }
682	    }
