684	    template <typename T>
685	    __aicore__ inline void ScatterUpdatePABlkBnsd(
686	        const GlobalTensor<T>& dst, const GlobalTensor<T>& dstNd, const LocalTensor<T>& outLocal, int64_t startIdx,
687	        int64_t rows, int64_t headSize)
688	    {
689	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(headSize * sizeof(T)), 0, 0, 0};
690	        int64_t indexPageLength =
691	            (this->tilingData_->seqLength + this->tilingData_->blockSize - 1) / this->tilingData_->blockSize;
692	        int64_t pageIdOffset = this->tilingData_->blockSize * headSize * this->tilingData_->numHead;
693	        for (int64_t i = 0; i < rows; i++) {
694	            int64_t tokenId = startIdx + i;
695	            int64_t ubOffset = headSize * i;
696	            if (this->tilingData_->isOutputKv) {
697	                int64_t gmOffsetNd = tokenId * headSize;
698	                DataCopyPad(dstNd[gmOffsetNd], outLocal[ubOffset], copyParams);
699	            }
700	
701	            // Index: (B*ceil(S/bs),)
702	            // Cache[𝐼𝑛𝑑𝑒𝑥[𝑏∗(𝑠/𝑏𝑠)],𝑠%𝑏𝑠,𝑛,𝑑]=𝑉𝑎𝑙𝑢𝑒[𝑏,𝑛,𝑠,𝑑]
703	            int64_t tokensPerBatch = this->tilingData_->seqLength * this->tilingData_->numHead;
704	            int64_t batchId = tokenId / tokensPerBatch;
705	            int64_t tokenInBatch = tokenId % tokensPerBatch;               // token in batch
706	            int64_t headIdx = tokenInBatch / this->tilingData_->seqLength; // numHead
707	            int64_t seqIdx = tokenInBatch % this->tilingData_->seqLength;  // seq
708	
709	            int64_t indexPageId = seqIdx / this->tilingData_->blockSize;
710	            int64_t indexOffset = batchId * indexPageLength + indexPageId;
711	            int64_t pageOffset = this->indexGm(indexOffset);
712	            int64_t tokenOffsetInCurrentPage = seqIdx % this->tilingData_->blockSize;
713	            int64_t pageId = pageOffset / this->tilingData_->blockSize;
714	            if (pageOffset >= 0) {
715	                // [BlockNum, BlockSize, N, headSize]
716	                int64_t gmOffset = pageId * pageIdOffset +
717	                                   tokenOffsetInCurrentPage * this->tilingData_->numHead * headSize +
718	                                   headIdx * headSize;
719	                SToMTE3Sync();
720	                DataCopyPad(dst[gmOffset], outLocal[ubOffset], copyParams);
721	            }
722	        }
723	    }
