769	    // ScatterUpdate with stride for non-contiguous dim-0 (only for ProcessV1)
770	    template <typename T>
771	    __aicore__ inline void DoScatterWithStride(
772	        const GlobalTensor<T>& dst, const GlobalTensor<T>& dstNd, const LocalTensor<T>& outLocal, int64_t startIdx,
773	        int64_t rows, int64_t headSize, int64_t stride)
774	    {
775	        PipeBarrier<PIPE_ALL>();
776	        // Bnsd with stride: decompose offset into page/token for stride
777	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(headSize * sizeof(T)), 0, 0, 0};
778	        for (int64_t i = 0; i < rows; i++) {
779	            int64_t tokenId = startIdx + i;
780	            int64_t ubOffset = headSize * i;
781	            if (this->tilingData_->isOutputKv) {
782	                DataCopyPad(dstNd[tokenId * headSize], outLocal[ubOffset], copyParams);
783	            }
784	            int64_t tokensPerBatch = this->tilingData_->seqLength * this->tilingData_->numHead;
785	            int64_t batchId = tokenId / tokensPerBatch;
786	            int64_t tokenInBatch = tokenId % tokensPerBatch;
787	            int64_t headIdx = tokenInBatch / this->tilingData_->seqLength;
788	            int64_t seqIdx = tokenInBatch % this->tilingData_->seqLength;
789	            int64_t offset = this->indexGm(batchId * this->tilingData_->seqLength + seqIdx);
790	            if (offset >= 0) {
791	                int64_t pageIdx = offset / this->tilingData_->blockSize;
792	                int64_t tokenInPage = offset % this->tilingData_->blockSize;
793	                int64_t gmOffset = pageIdx * stride + tokenInPage * headSize * this->tilingData_->numHead +
794	                                   headIdx * headSize; // 多头下stride的定义？
795	                SToMTE3Sync();
796	                DataCopyPad(dst[gmOffset], outLocal[ubOffset], copyParams);
797	            }
798	        }
799	        PipeBarrier<PIPE_ALL>();
800	    }
