802	    // ScatterUpdate for merged k/v cache (cacheLayOut == 1, only for ProcessV1)
803	    // Writes headSize elements to dst at dimOffset within a combined totalHeadSize dimension
804	    // Internally handles stride > blockSize for non-contiguous dim-0
805	    template <typename T, int64_t isSFACountiguous>
806	    __aicore__ inline void DoScatterMerged(
807	        const GlobalTensor<T>& dst, const GlobalTensor<T>& dstNd, const LocalTensor<T>& outLocal, int64_t startIdx,
808	        int64_t rows, int64_t headSize, int64_t totalHeadSize, int64_t dimOffset)
809	    {
810	        PipeBarrier<PIPE_ALL>();
811	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(headSize * sizeof(T)), 0, 0, 0};
812	        for (int64_t i = 0; i < rows; i++) {
813	            int64_t tokenId = startIdx + i;
814	            int64_t ubOffset = headSize * i;
815	            if (this->tilingData_->isOutputKv) {
816	                DataCopyPad(dstNd[tokenId * headSize], outLocal[ubOffset], copyParams);
817	            }
818	
819	            int64_t tokensPerBatch = this->tilingData_->seqLength * this->tilingData_->numHead;
820	            int64_t batchId = tokenId / tokensPerBatch;
821	            int64_t tokenInBatch = tokenId % tokensPerBatch;
822	            int64_t headIdx = tokenInBatch / this->tilingData_->seqLength;
823	            int64_t seqIdx = tokenInBatch % this->tilingData_->seqLength;
824	
825	            int64_t offset = this->indexGm(batchId * this->tilingData_->seqLength + seqIdx);
826	            if (offset >= 0) {
827	                int64_t gmOffset = -1;
828	                if constexpr (isSFACountiguous != SFA_COUNTIGUOUS) {
829	                    int64_t pageIdx = offset / this->tilingData_->blockSize;
830	                    int64_t tokenInPage = offset % this->tilingData_->blockSize;
831	                    gmOffset = pageIdx * vStride + tokenInPage * totalHeadSize * this->tilingData_->numHead +
832	                               headIdx * totalHeadSize + dimOffset; // 多头下stride的定义？
833	                } else {
834	                    gmOffset =
835	                        offset * totalHeadSize * this->tilingData_->numHead + headIdx * totalHeadSize + dimOffset;
836	                }
837	                SToMTE3Sync();
838	                DataCopyPad(dst[gmOffset], outLocal[ubOffset], copyParams);
839	            }
840	        }
841	        PipeBarrier<PIPE_ALL>();
842	    }
