844	    template <typename T, int64_t D1, int64_t D0, int64_t clLayout, int64_t isSFACountiguous>
845	    __aicore__ inline void DoScatterV1(
846	        const GlobalTensor<T>& dst, const GlobalTensor<T>& dstNd, const LocalTensor<T>& outLocal, int64_t startIdx,
847	        int64_t rows, int64_t headSize, bool isKCache, int64_t stride)
848	    {
849	        if constexpr (clLayout == SFA_NO_QUANT) {
850	            int64_t totalHeadSize = this->RMS_NORM_LENGTH + this->ROPE_LENGTH;
851	            int64_t dimOffset = isKCache ? this->RMS_NORM_LENGTH : 0;
852	            DoScatterMerged<T, isSFACountiguous>(
853	                this->vCacheGm, dstNd, outLocal, startIdx, rows, headSize, totalHeadSize, dimOffset);
854	        } else if constexpr (clLayout == SWA_MODE) {
855	            DoScatterWithStride<T>(dst, dstNd, outLocal, startIdx, rows, headSize, stride);
856	        } else if constexpr (clLayout == CONTIGUOUS) {
857	            DoScatter<T, D1, D0>(dst, dstNd, outLocal, startIdx, rows, headSize);
858	        }
