861	    template <typename T>
862	    __aicore__ inline void RmsNorm(
863	        const LocalTensor<T>& outLocal, const LocalTensor<T>& xLocal, const LocalTensor<float>& gammaLocal,
864	        const LocalTensor<float>& wsLocal, int64_t rows, int64_t headSize)
865	    {
866	        constexpr static int64_t NUM_EIGHT = 8;
867	        constexpr static int64_t NUM_SIXTEEN = 16;
868	        constexpr static int64_t NUM_SIXTY_FOUR = 64;
869	        int64_t xLocalFp32Offset = 0;                  // [0, rows * headSize]
870	        int64_t xSquareLocalOffset = rows * headSize;  // [rows * headSize, rows * headSize * 2]
871	        int64_t xSumLocalOffset = rows * headSize * 2; // [rows * headSize * 2, rows * headSize * 3]
872	        LocalTensor<float> xLocalFp32 = wsLocal[xLocalFp32Offset];
873	        LocalTensor<float> xSquareLocal = wsLocal[xSquareLocalOffset];
874	        LocalTensor<float> xSumLocal = wsLocal[xSumLocalOffset];
875	
876	        Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, rows * headSize);
877	        PipeBarrier<PIPE_V>();
878	        Mul(xSquareLocal, xLocalFp32, xLocalFp32, rows * headSize);
879	        PipeBarrier<PIPE_V>();
880	        int64_t repeatTimes = rows * (headSize >> 1) / NUM_SIXTY_FOUR;
881	        Add(xSquareLocal[0], xSquareLocal[0], xSquareLocal[NUM_SIXTY_FOUR], NUM_SIXTY_FOUR, repeatTimes,
882	            {1, 1, 1, NUM_EIGHT, NUM_SIXTEEN, NUM_SIXTEEN}); // 256
883	        PipeBarrier<PIPE_V>();
884	        repeatTimes = repeatTimes / 2;
885	        Add(xSquareLocal[0], xSquareLocal[0], xSquareLocal[NUM_SIXTY_FOUR], NUM_SIXTY_FOUR, repeatTimes,
886	            {1, 1, 1, NUM_EIGHT, NUM_SIXTEEN, NUM_SIXTEEN}); // 128
887	        PipeBarrier<PIPE_V>();
888	        repeatTimes = repeatTimes / 2;
889	        Add(xSquareLocal[0], xSquareLocal[0], xSquareLocal[NUM_SIXTY_FOUR], NUM_SIXTY_FOUR, repeatTimes,
890	            {1, 1, 1, NUM_EIGHT, NUM_SIXTEEN, NUM_SIXTEEN}); // 64
891	        PipeBarrier<PIPE_V>();
892	
893	        WholeReduceSum(xSumLocal, xSquareLocal, NUM_SIXTY_FOUR, rows, 1, 1, NUM_EIGHT);
894	        PipeBarrier<PIPE_V>();
895	        // Calc: xSum = xSum * reciprocal
896	        Muls<float>(xSumLocal, xSumLocal, this->tilingData_->reciprocal, rows);
897	        PipeBarrier<PIPE_V>();
898	        // Calc: xSum = xSum + epsilon
899	        Adds<float>(xSumLocal, xSumLocal, this->tilingData_->epsilon, rows);
900	        PipeBarrier<PIPE_V>();
901	        // Calc: xSum = sqrt(xSum)
902	        Sqrt(xSumLocal, xSumLocal, rows);
903	        PipeBarrier<PIPE_V>();
904	
905	        // Brcb
906	        int64_t block_count = (rows + NUM_EIGHT - 1) / NUM_EIGHT;
907	        Brcb(xSquareLocal, xSumLocal, block_count, {1, NUM_EIGHT});
908	        PipeBarrier<PIPE_V>();
909	
910	        // Calc: xLocalFp32 = xLocalFp32 / xSquareLocal
911	        for (int64_t rowId = 0; rowId < rows; rowId++) {
912	            Div(xLocalFp32[rowId * headSize], xLocalFp32[rowId * headSize], xSquareLocal[rowId * NUM_EIGHT],
913	                NUM_SIXTY_FOUR, (headSize / NUM_SIXTY_FOUR), {1, 1, 0, NUM_EIGHT, NUM_EIGHT, 0});
914	        }
915	        PipeBarrier<PIPE_V>();
916	
917	        // Calc: xLocalFp32 = xLocalFp32 * xSquareLocal [rows, this->RMS_NORM_LENGTH] * [this->RMS_NORM_LENGTH]
918	        for (int64_t rowId = 0; rowId < rows; rowId++) {
919	            Mul(xLocalFp32[rowId * headSize], xLocalFp32[rowId * headSize], gammaLocal, headSize);
920	        }
921	        PipeBarrier<PIPE_V>();
922	
923	        // Cast xLocalFp32 to outLocal
