36	    {
37	        // 获取分块操作中的单个块的大小。判断是否是最后一块，是最后一块，则等于剩余元素的数量，否则等于固定的单核处理的行数
38	        int64_t currentBlockFactor = tilingData_->blockFactor;
39	        if (this->blockIdx == (this->useCoreNum - 1)) {
40	            currentBlockFactor =
41	                tilingData_->batchSize * tilingData_->seqLength - (this->useCoreNum - 1) * tilingData_->blockFactor;
42	        }
43	        this->reciprocal = tilingData_->reciprocal;
44	        this->epsilon = tilingData_->epsilon;
45	        this->dv = tilingData_->dv;
46	        this->dvAlign = tilingData_->dvAlign;
47	        this->dvB8Align = tilingData_->dvB8Align;
48	        this->dkAlign = tilingData_->dkAlign;
49	        this->dk = tilingData_->dk;
50	        this->ubFactor = tilingData_->ubFactor;
51	        this->dynamicScaleAlign = tilingData_->dynamicScaleAlign;
52	        // NZ参数
53	        dk0 = BLOCK_SIZE / sizeof(T_K_CACHE);
54	        dk1 = this->dk / dk0;
55	        dv0 = BLOCK_SIZE / sizeof(T_V_CACHE);
56	        dv1 = this->dv / dv0;
57	
58	        copyOutKParams.blockCount = 1;
