60	        copyOutKParams.srcStride = 0;
61	        copyOutKParams.dstStride = 0;
62	
63	        copyOutKParamsNz.blockCount = dk1;
64	        copyOutKParamsNz.blockLen = dk0 * sizeof(T_K_CACHE);
65	        copyOutKParamsNz.srcStride = 0;
66	        copyOutKParamsNz.dstStride = (tilingData_->blockSize - 1) * dk0 * sizeof(T_K_CACHE);
67	
68	        copyOutVParams.blockCount = 1;
69	        copyOutVParams.blockLen = tilingData_->dv * sizeof(T_V_CACHE);
70	        copyOutVParams.srcStride = 0;
71	        copyOutVParams.dstStride = 0;
72	
73	        copyOutVParamsNz.blockCount = dv1;
74	        copyOutVParamsNz.blockLen = dv0 * sizeof(T_V_CACHE);
75	        copyOutVParamsNz.srcStride = 0;
76	        copyOutVParamsNz.dstStride = (tilingData_->blockSize - 1) * dv0 * sizeof(T_V_CACHE);
77	
78	        copyOutMergedKCacheParams.blockCount = 1;
79	        copyOutMergedKCacheParams.blockLen = tilingData_->dk * sizeof(T_K_CACHE);
80	        copyOutMergedKCacheParams.srcStride = 0;
81	        copyOutMergedKCacheParams.dstStride = 0;
82	
83	        copyOutMergedVCacheParams.blockCount = 1;
84	        copyOutMergedVCacheParams.blockLen = tilingData_->dv * sizeof(T_V_CACHE);
85	        copyOutMergedVCacheParams.srcStride = 0;
86	        copyOutMergedVCacheParams.dstStride = 0;
87	
88	        copyOutMergedScaleVCacheParams.blockCount = 1;
89	        copyOutMergedScaleVCacheParams.blockLen = (tilingData_->dv / tilingData_->pertileSize) * sizeof(float);
90	        copyOutMergedScaleVCacheParams.srcStride = 0;
91	        copyOutMergedScaleVCacheParams.dstStride = 0;
92	
93	        // ubLoop: 表示需要多少个子块来覆盖singleA大小的数据
94	        this->ubLoop = (currentBlockFactor + this->ubFactor - 1) / this->ubFactor;
95	        // ubLoop：最后一块
96	        this->ubTail = currentBlockFactor - (this->ubLoop - 1) * this->ubFactor;
97	        dKV = (tilingData_->dk + tilingData_->dv);
98	        kScaleCopyLen = tilingData_->kScaleType == 1 ? 1 : tilingData_->halfDk;
