101	        kOffsetCopyOffset = tilingData_->kOffsetType == 1 ? 0 : tilingData_->halfDk;
102	        vScaleCopyLen = tilingData_->vScaleType == 1 ? 1 : tilingData_->dv;
103	        vOffsetCopyLen = tilingData_->vOffsetType == 1 ? 1 : tilingData_->dv;
104	
105	        kVFLoop = ops::FloorDiv(tilingData_->halfDk, static_cast<int64_t>(VL_FP32));
106	        kVFTail = tilingData_->halfDk % VL_FP32;
107	
108	        this->dvLoopCount = ops::CeilDiv(tilingData_->dv, static_cast<int64_t>(VL_FP32));
109	
110	        // init global memory
111	        this->kvGm.SetGlobalBuffer((__gm__ T_KV*)kv + this->blockIdx * tilingData_->blockFactor * dKV);
112	        this->gammaGm.SetGlobalBuffer((__gm__ T_KV*)gamma);
