118	        this->kScaleGm.SetGlobalBuffer((__gm__ float*)k_scale);
119	        this->vScaleGm.SetGlobalBuffer((__gm__ float*)v_scale);
120	        this->kOffsetGm.SetGlobalBuffer((__gm__ float*)k_offset);
