134	
135	        if (tilingData_->kQuantMode == SYM_QUANT_MODE || tilingData_->kQuantMode == ASYM_QUANT_MODE) {
136	            pipe_->InitBuffer(
137	                kScaleOffsetQueue, BUFFER_COUNT_SINGLE,
138	                K_SCALE_OFFSET_CHANNEL_COUNT * tilingData_->halfDkAlign * sizeof(float));
139	        }
140	
141	        if (tilingData_->vQuantMode == SYM_QUANT_MODE || tilingData_->vQuantMode == ASYM_QUANT_MODE) {
142	            pipe_->InitBuffer(
143	                vScaleOffsetQueue, BUFFER_COUNT_SINGLE,
144	                V_SCALE_OFFSET_CHANNEL_COUNT * tilingData_->dvAlign * sizeof(float));
145	        } else if (tilingData_->vQuantMode == V_PERTILE_128_QUANT_MODE) {
146	            if constexpr (IsSameType<T_V_CACHE, int8_t>::value) {
147	                this->dynamicQuantFactor = INT8_MAX_SCALE;
