22	
23	template <typename T>
24	class RotateHalf : public RotateHalfBase<T, T> {
25	public:
26	    __aicore__ inline RotateHalf(){};
27	    __aicore__ inline void Init(
28	        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y, const AiInfraRotaryPositionEmbeddingTilingData &tilingData);
29	    __aicore__ inline void Process();
