31	protected:
32	    TPipe pipe;
33	    TQue<QuePosition::VECIN, DOUBLE_BUFFER> inQueueX;
34	    TQue<QuePosition::VECIN, DOUBLE_BUFFER> inQueueCos;
35	    TQue<QuePosition::VECIN, DOUBLE_BUFFER> inQueueSin;
36	    TQue<QuePosition::VECOUT, DOUBLE_BUFFER> outQueueY;
37	    GlobalTensor<T> xGm;
38	    GlobalTensor<T> cosGm;
39	    GlobalTensor<T> sinGm;
40	    GlobalTensor<T> yGm;
41	
42	    __aicore__ inline void NormalProcess();
43	    __aicore__ inline void RB1sdProcess();
44	    __aicore__ inline void BndProcess();
45	    __aicore__ inline void SingleStepProcess(
46	        uint32_t progress, uint32_t sLines, uint64_t copyLength, uint64_t calcLength);
47	    __aicore__ inline void RB1sdSingleStepProcess(uint32_t progress, uint32_t sLines, uint64_t xBatchStartOffset,
48	        uint64_t rBatchStartOffset, uint64_t copyLength, uint64_t calcLength);
49	    __aicore__ inline void Compute(LocalTensor<T> &cos, LocalTensor<T> &sin, uint32_t sLines, uint32_t calcLength);
50	    __aicore__ inline void CopyInR(uint64_t rStartOffset, uint16_t sLines, uint32_t copyLength);
51	    __aicore__ inline void CopyInX(uint64_t xStartOffset, uint16_t sLines, uint32_t copyLength);
52	    __aicore__ inline void CopyOut(uint64_t yStartOffset, uint16_t sLines, uint32_t copyLength);
53	};
54	
55	template <typename T>
56	__aicore__ inline void RotateHalf<T>::Init(
57	    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y, const AiInfraRotaryPositionEmbeddingTilingData &tilingData)
58	{
59	    this->BaseMemberInit(tilingData);
60	
61	    xGm.SetGlobalBuffer((__gm__ T *)x + this->xOffset + this->xCoreOffset * this->coreRelativeIdx, this->xAllocLength);
62	    yGm.SetGlobalBuffer((__gm__ T *)y + this->xOffset + this->xCoreOffset * this->coreRelativeIdx, this->xAllocLength);
63	    cosGm.SetGlobalBuffer(
64	        (__gm__ T *)cos + this->rOffset + this->rCoreOffset * this->coreRelativeIdx, this->rAllocLength);
65	    sinGm.SetGlobalBuffer(
66	        (__gm__ T *)sin + this->rOffset + this->rCoreOffset * this->coreRelativeIdx, this->rAllocLength);
67	
68	    pipe.InitBuffer(inQueueX, DOUBLE_BUFFER, this->storePadDataLength * sizeof(T));
69	    pipe.InitBuffer(outQueueY, DOUBLE_BUFFER, this->storePadDataLength * sizeof(T));
70	    pipe.InitBuffer(inQueueCos, DOUBLE_BUFFER, this->storePadDataLength * sizeof(T));
71	    pipe.InitBuffer(inQueueSin, DOUBLE_BUFFER, this->storePadDataLength * sizeof(T));
72	}
73	
74	template <typename T>
75	__aicore__ inline void RotateHalf<T>::Process()
76	{
77	    if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_BSND || this->layout == LAYOUT_SBND ||
78	        this->layout == LAYOUT_NO_BROADCAST) {
79	        NormalProcess();
80	    } else if (this->layout == LAYOUT_R_B1SD) {
81	        RB1sdProcess();
82	    } else if (this->layout == LAYOUT_BND) {
83	        BndProcess();
84	    }
85	}
86	
87	template <typename T>
88	__aicore__ inline void RotateHalf<T>::NormalProcess()
89	{
90	    for (uint32_t progress = 0; progress < this->ubLoop; progress++) {
91	        SingleStepProcess(progress, this->storeSLines, this->storeDataLength, this->storePadDataLength);
92	    }
93	    if (this->ubLast > 0) {
94	        SingleStepProcess(this->ubLoop, this->ubLast, this->ubLastDataLength, this->ubLastPadDataLength);
95	    }
96	}
97	
98	template <typename T>
99	__aicore__ inline void RotateHalf<T>::RB1sdProcess()
100	{
101	    uint64_t totalSdLength = this->totalSLines * this->dLength;
102	    uint64_t totalNsdLength = totalSdLength * this->bcSecondDim;
103	    for (uint32_t batchLoop = 0; batchLoop < this->bcFirstDim; batchLoop++) {
104	        uint64_t xBatchOffset = batchLoop * totalNsdLength;
105	        uint64_t rBatchOffset = batchLoop * totalSdLength;
106	        for (uint32_t progress = 0; progress < this->ubLoop; progress++) {
107	            RB1sdSingleStepProcess(progress,
108	                this->storeSLines,
109	                xBatchOffset,
110	                rBatchOffset,
111	                this->storeDataLength,
112	                this->storePadDataLength);
113	        }
114	        if (this->ubLast > 0) {
115	            RB1sdSingleStepProcess(this->ubLoop,
116	                this->ubLast,
117	                xBatchOffset,
118	                rBatchOffset,
119	                this->ubLastDataLength,
120	                this->ubLastPadDataLength);
121	        }
122	    }
123	}
124	
125	template <typename T>
126	__aicore__ inline void RotateHalf<T>::BndProcess()
127	{
128	    CopyInR(0, 1, this->dLength);
129	    LocalTensor<T> cosLocal = inQueueCos.DeQue<T>();
130	    LocalTensor<T> sinLocal = inQueueSin.DeQue<T>();
131	    Muls(sinLocal, sinLocal, (T)(-1.0), this->halfDPadLength);
132	    uint32_t broadcastLines = this->ubLoop > 0 ? this->storeSLines - 1 : this->ubLast - 1;
133	    if (broadcastLines > 0) {
134	        this->RBroadCast(cosLocal, sinLocal, broadcastLines);
135	    }
136	    uint64_t xOffset;
137	    for (uint32_t progress = 0; progress < this->ubLoop; progress++) {
138	        xOffset = progress * this->storeDataLength;
139	        CopyInX(xOffset, this->storeSLines, this->storeDataLength);
140	        Compute(cosLocal, sinLocal, this->storeSLines, this->storePadDataLength);
141	        CopyOut(xOffset, this->storeSLines, this->storeDataLength);
142	    }
143	    if (this->ubLast > 0) {
144	        xOffset = this->ubLoop * this->storeDataLength;
145	        CopyInX(xOffset, this->ubLast, this->ubLastDataLength);
146	        Compute(cosLocal, sinLocal, this->ubLast, this->ubLastPadDataLength);
147	        CopyOut(xOffset, this->ubLast, this->ubLastDataLength);
148	    }
149	    inQueueCos.FreeTensor(cosLocal);
150	    inQueueSin.FreeTensor(sinLocal);
151	}
152	
153	template <typename T>
154	__aicore__ inline void RotateHalf<T>::SingleStepProcess(
155	    uint32_t progress, uint32_t sLines, uint64_t copyLength, uint64_t calcLength)
156	{
157	    uint64_t xOffset, rOffset, bnLoopXStartOffset, progressOffset, batchOffset;
158	    rOffset = progress * this->storeDataLength;
159	    CopyInR(rOffset, sLines, copyLength);
160	    LocalTensor<T> cosLocal = inQueueCos.DeQue<T>();
161	    LocalTensor<T> sinLocal = inQueueSin.DeQue<T>();
162	    this->SinCompute(sinLocal, sLines);
163	
164	    if (this->layout == LAYOUT_BNSD) {
165	        uint64_t totalSdSize = this->totalSLines * this->dLength;
166	        bnLoopXStartOffset = progress * this->storeDataLength;
167	        for (uint32_t bnLoop = 0; bnLoop < this->bnSize; bnLoop++) {
168	            xOffset = bnLoopXStartOffset + bnLoop * totalSdSize;
169	            CopyInX(xOffset, sLines, copyLength);
170	            Compute(cosLocal, sinLocal, sLines, calcLength);
171	            CopyOut(xOffset, sLines, copyLength);
172	        }
173	    } else if (this->layout == LAYOUT_BSND) {
174	        uint64_t totalSndSize = this->totalSLines * this->ndSize;
175	        progressOffset = progress * this->bcSecondDim * this->storeDataLength;
176	        for (uint32_t bLoop = 0; bLoop < this->bcFirstDim; bLoop++) {
177	            batchOffset = bLoop * totalSndSize;
178	            for (uint32_t nLoop = 0; nLoop < this->bcSecondDim; nLoop++) {
179	                xOffset = nLoop * this->dLength + batchOffset + progressOffset;
180	                CopyInX(xOffset, sLines, copyLength);
181	                Compute(cosLocal, sinLocal, sLines, calcLength);
182	                CopyOut(xOffset, sLines, copyLength);
183	            }
184	        }
185	    } else if (this->layout == LAYOUT_SBND) {
186	        bnLoopXStartOffset = progress * this->storeDataLength * this->bnSize;
187	        for (uint32_t bnLoop = 0; bnLoop < this->bnSize; bnLoop++) {
188	            xOffset = bnLoopXStartOffset + bnLoop * this->dLength;
189	            CopyInX(xOffset, sLines, copyLength);
190	            Compute(cosLocal, sinLocal, sLines, calcLength);
191	            CopyOut(xOffset, sLines, copyLength);
192	        }
193	    } else if (this->layout == LAYOUT_NO_BROADCAST) {
194	        CopyInX(rOffset, sLines, copyLength);
195	        Compute(cosLocal, sinLocal, sLines, calcLength);
196	        CopyOut(rOffset, sLines, copyLength);
197	    }
198	    inQueueCos.FreeTensor<T>(cosLocal);
199	    inQueueSin.FreeTensor<T>(sinLocal);
200	}
