243	template <typename T>
244	__aicore__ inline void RotateHalf<T>::CopyInX(uint64_t xStartOffset, uint16_t sLines, uint32_t copyLength)
245	{
246	    LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
247	    DataCopyExtParams copyParams{};
248	
249	    if (this->isAligned == true) {
250	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
251	            this->layout == LAYOUT_R_B1SD) {
252	            DataCopy(xLocal, xGm[xStartOffset], copyLength);
253	        } else {
254	            copyParams.blockCount = sLines;
255	            copyParams.blockLen = this->dBytes;
256	            copyParams.dstStride = 0;
