293	template <typename T>
294	__aicore__ inline void RotateHalf<T>::CopyOut(uint64_t yStartOffset, uint16_t sLines, uint32_t copyLength)
295	{
296	    LocalTensor<T> yLocal = outQueueY.DeQue<T>();
297	    DataCopyExtParams copyParams{};
298	
299	    if (this->isAligned == true) {
300	        copyParams.blockCount = sLines;
301	        copyParams.blockLen = this->dBytes;
