313	        }
314	    } else {
315	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
316	            this->layout == LAYOUT_R_B1SD) {
317	            copyParams.blockCount = (uint16_t)(2 * sLines);
318	            copyParams.blockLen = this->halfDBytes;
319	            copyParams.srcStride = 0;
320	            copyParams.dstStride = 0;
321	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
322	        } else if (this->layout == LAYOUT_BSND) {
323	            copyParams.blockCount = sLines;
324	            copyParams.blockLen = this->halfDBytes;
325	            copyParams.srcStride = this->halfDPadBlocks;
326	            copyParams.dstStride = (2 * this->bcSecondDim - 1) * this->halfDBytes;
327	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
328	            DataCopyPad(yGm[yStartOffset + this->halfDLength], yLocal[this->halfDPadLength], copyParams);
329	        } else if (this->layout == LAYOUT_SBND) {
330	            copyParams.blockCount = sLines;
331	            copyParams.blockLen = this->halfDBytes;
332	            copyParams.srcStride = this->halfDPadBlocks;
333	            copyParams.dstStride = (2 * this->bnSize - 1) * this->halfDBytes;
334	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
