341	template <typename T>
342	__aicore__ inline void RotateHalf<T>::Compute(
343	    LocalTensor<T> &cos, LocalTensor<T> &sin, uint32_t sLines, uint32_t calcLength)
344	{
345	    LocalTensor<T> xLocal = inQueueX.DeQue<T>();
346	    LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
