221	/* Split S lines to each core, former core maybe deal one more line than tail core. */
222	inline void RotateHalfTiling::GetCoreDataTiling()
223	{
224	    uint64_t formerCoreNum;
225	    uint64_t tailCoreNum;
226	    uint64_t totalS = tilingData_.get_totalSLines();
227	    // calc former and tail core num
228	    if (totalS <= coreNum) {
229	        formerCoreNum = totalS;
230	        tailCoreNum = 0;
231	        coreNum = totalS;
232	    } else {
233	        formerCoreNum = GetRem(totalS, coreNum);
234	        tailCoreNum = coreNum - formerCoreNum;
235	    }
236	    // S lines each core
237	    uint64_t formerSLines = GetCeilDiv(totalS, coreNum);
238	    uint64_t tailSLines = GetDiv(totalS, coreNum);
239	
240	    tilingData_.set_formerCoreNum(formerCoreNum);
241	    tilingData_.set_formerSLines(formerSLines);
242	    tilingData_.set_tailCoreNum(tailCoreNum);
243	    tilingData_.set_tailSLines(tailSLines);
244	}
245	
246	/* Calc ub loop times and left S lines in each core */
247	inline void RotateHalfTiling::GetUbLoopTiling()
248	{
249	    uint64_t tilingMode = tilingData_.get_tilingMode();
250	    uint64_t formerSLines = tilingData_.get_formerSLines();
251	    uint64_t tailSLines = tilingData_.get_tailSLines();
252	    uint64_t storeSLines = tilingData_.get_storeSLines();
253	    uint64_t dLength = tilingData_.get_dLength();
254	    uint64_t dPadLength = tilingData_.get_dPadLength();
255	
256	    // each core ub loop
257	    tilingData_.set_formerUbLoop(GetDiv(formerSLines, storeSLines));
258	    tilingData_.set_tailUbLoop(GetDiv(tailSLines, storeSLines));
259	    // each core ub last lines after loop
260	    tilingData_.set_formerUbLast(GetRem(formerSLines, storeSLines));
261	    tilingData_.set_tailUbLast(GetRem(tailSLines, storeSLines));
262	
263	    // each core processed data length
264	    GetUbLoopCoreDataLength(tilingMode, formerSLines, tailSLines, dLength);
265	
266	    // each ub loop processed data length == storeDataLength
267	    // ub last processed data length
268	    tilingData_.set_formerUbLastDataLength(tilingData_.get_formerUbLast() * dLength);
269	    tilingData_.set_tailUbLastDataLength(tilingData_.get_tailUbLast() * dLength);
270	    tilingData_.set_formerUbLastPadDataLength(tilingData_.get_formerUbLast() * dPadLength);
271	    tilingData_.set_tailUbLastPadDataLength(tilingData_.get_tailUbLast() * dPadLength);
272	
273	    // former core processed total data length(the start offset of tail cores)
274	    GetUbLoopCoreOffset(tilingMode, formerSLines, dLength);
275	}
276	
277	inline void RotateHalfTiling::GetUbLoopCoreDataLength(
278	    const uint64_t tilingMode, const uint64_t formerSLines, const uint64_t tailSLines, const uint64_t dLength)
279	{
280	    uint64_t bSize = tilingData_.get_broadcastFirstDim();
281	    uint64_t nSize = tilingData_.get_broadcastSecondDim();
282	    uint64_t bnSize = bSize * nSize;
283	    uint64_t bdSize = bSize * dLength;
284	    uint64_t bndSize = bnSize * dLength;
285	
286	    if (tilingMode == TILING_MODE_BNSD || tilingMode == TILING_MODE_BSND || tilingMode == TILING_MODE_SBND ||
287	        tilingMode == TILING_MODE_NO_BROADCAST) {
288	        tilingData_.set_formerXDataLength(formerSLines * bndSize);
289	        tilingData_.set_tailXDataLength(tailSLines * bndSize);
290	        tilingData_.set_formerRDataLength(formerSLines * dLength);
291	        tilingData_.set_tailRDataLength(tailSLines * dLength);
292	    } else if (tilingMode == TILING_MODE_BND) {
293	        tilingData_.set_formerXDataLength(formerSLines * dLength);
294	        tilingData_.set_tailXDataLength(tailSLines * dLength);
295	        tilingData_.set_formerRDataLength(dLength);
296	        tilingData_.set_tailRDataLength(dLength);
297	    } else if (tilingMode == TILING_MODE_R_B1SD) {
298	        tilingData_.set_formerXDataLength(formerSLines * bndSize);
299	        tilingData_.set_tailXDataLength(tailSLines * bndSize);
300	        tilingData_.set_formerRDataLength(formerSLines * bdSize);
301	        tilingData_.set_tailRDataLength(tailSLines * bdSize);
302	    } else {
303	        OP_LOGD(context, "tilingMode is unknown");
304	    }
305	}
306	
307	inline void RotateHalfTiling::GetUbLoopCoreOffset(
308	    const uint64_t tilingMode, const uint64_t formerSLines, const uint64_t dLength)
309	{
310	    uint64_t bSize = tilingData_.get_broadcastFirstDim();
311	    uint64_t nSize = tilingData_.get_broadcastSecondDim();
312	    uint64_t ndSize = nSize * dLength;
313	    uint64_t bndSize = bSize * nSize * dLength;
314	
315	    tilingData_.set_formerRCoreOffset(tilingData_.get_formerCoreNum() * formerSLines * dLength);
316	    if (tilingMode == TILING_MODE_BNSD || tilingMode == TILING_MODE_NO_BROADCAST || tilingMode == TILING_MODE_R_B1SD) {
317	        tilingData_.set_formerXCoreOffset(tilingData_.get_formerCoreNum() * formerSLines * dLength);
318	    } else if (tilingMode == TILING_MODE_BSND) {
319	        tilingData_.set_formerXCoreOffset(tilingData_.get_formerCoreNum() * formerSLines * ndSize);
320	    } else if (tilingMode == TILING_MODE_SBND) {
321	        tilingData_.set_formerXCoreOffset(tilingData_.get_formerCoreNum() * formerSLines * bndSize);
322	    } else if (tilingMode == TILING_MODE_BND) {
323	        tilingData_.set_formerXCoreOffset(tilingData_.get_formerCoreNum() * formerSLines * dLength);
324	        tilingData_.set_formerRCoreOffset(0);
325	    } else {
326	        OP_LOGD(context, "tilingMode is unknown");
327	    }
328	}
329	
330	/* Cut UB size to ubNum, compute how many Lines of D_pad(split S) can store in each split UB */
331	inline void RotateHalfTiling::GetStoreLines(
332	    const uint64_t ubSize, const uint64_t bytePerData, const ge::DataType &dtype)
333	{
334	    uint64_t ubNum = dtype == ge::DT_FLOAT ? DOUBLE_BUFFER * UB_NUM : DOUBLE_BUFFER * UB_NUM_BF16;
335	    uint64_t splitUbSize = GetDiv(ubSize - UB_RESERVE_SIZE, ubNum);
336	    uint64_t storeSLines = GetDiv(splitUbSize, bytePerData * tilingData_.get_dPadLength());
337	    tilingData_.set_storeSLines(storeSLines);
338	    tilingData_.set_storeDataLength(storeSLines * tilingData_.get_dLength());
339	    tilingData_.set_storePadDataLength(storeSLines * tilingData_.get_dPadLength());
340	}
