346	    tilingData_.set_broadcastFirstDim(NO_BROADCAST_DIM);
347	    tilingData_.set_broadcastSecondDim(NO_BROADCAST_DIM);
348	    tilingData_.set_totalSLines(x.dim1 * x.dim2 * x.dim3);
349	}
