351	inline void RotateHalfTiling::SetTilingModeBND(const Dim3D &x)
352	{
353	    OP_LOGD(context, "RotateHalf layout: BND");
354	    tilingData_.set_tilingMode(TILING_MODE_BND);
355	    tilingData_.set_broadcastFirstDim(NO_BROADCAST_DIM);
356	    tilingData_.set_broadcastSecondDim(NO_BROADCAST_DIM);
357	    if (x.dim1 == 1) {
358	        tilingData_.set_totalSLines(x.dim2 * x.dim3);
359	    } else if (x.dim2 == 1) {
360	        tilingData_.set_totalSLines(x.dim1 * x.dim3);
361	    } else if (x.dim3 == 1) {
362	        tilingData_.set_totalSLines(x.dim1 * x.dim2);
363	    } else {
364	        OP_LOGD(context, "RotateHalf layout: BNSD_ALL_BROADCAST");
365	    }
