368	inline void RotateHalfTiling::SetTilingModeBroadcast(const Dim3D &x, const Dim3D &r)
369	{
370	    if (x.dim1 != r.dim1 && x.dim2 != r.dim2) {  // BNSD
371	        OP_LOGD(context, "RotateHalf layout: BNSD");
372	        tilingData_.set_tilingMode(TILING_MODE_BNSD);
373	        tilingData_.set_broadcastFirstDim(x.dim1);
374	        tilingData_.set_broadcastSecondDim(x.dim2);
375	        tilingData_.set_totalSLines(x.dim3);
376	    } else if (x.dim1 != r.dim1 && x.dim3 != r.dim3) {  // BSND
377	        OP_LOGD(context, "RotateHalf layout: BSND");
378	        tilingData_.set_tilingMode(TILING_MODE_BSND);
379	        tilingData_.set_broadcastFirstDim(x.dim1);
380	        tilingData_.set_broadcastSecondDim(x.dim3);
381	        tilingData_.set_totalSLines(x.dim2);
382	    } else if (x.dim2 != r.dim2 && x.dim3 != r.dim3) {  // SBND
383	        OP_LOGD(context, "RotateHalf layout: SBND");
384	        tilingData_.set_tilingMode(TILING_MODE_SBND);
385	        tilingData_.set_broadcastFirstDim(x.dim2);
386	        tilingData_.set_broadcastSecondDim(x.dim3);
387	        tilingData_.set_totalSLines(x.dim1);
388	    } else if (x.dim1 != r.dim1 && (r.dim2 == 1 || r.dim3 == 1)) {  // x: B1SD or BS1D
389	        OP_LOGD(context, "RotateHalf layout: x B1SD or BS1D");
390	        tilingData_.set_tilingMode(TILING_MODE_BSND);
391	        tilingData_.set_broadcastFirstDim(x.dim1);
392	        tilingData_.set_broadcastSecondDim(NO_BROADCAST_DIM);
393	        tilingData_.set_totalSLines(x.dim2 * x.dim3);
394	    } else if (x.dim2 != r.dim2 && r.dim3 == 1) {  // x: SB1D
395	        OP_LOGD(context, "RotateHalf layout: x SB1D");
396	        tilingData_.set_tilingMode(TILING_MODE_SBND);
397	        tilingData_.set_broadcastFirstDim(x.dim2);
398	        tilingData_.set_broadcastSecondDim(NO_BROADCAST_DIM);
399	        tilingData_.set_totalSLines(x.dim1);
400	    } else if (r.dim3 != x.dim3 && r.dim1 == x.dim1 && r.dim2 == x.dim2) {  // r: BS1D or SB1D
401	        OP_LOGD(context, "RotateHalf layout: r BS1D or SB1D");
402	        tilingData_.set_tilingMode(TILING_MODE_SBND);
403	        tilingData_.set_broadcastFirstDim(NO_BROADCAST_DIM);
404	        tilingData_.set_broadcastSecondDim(x.dim3);
405	        tilingData_.set_totalSLines(x.dim1 * x.dim2);
406	    } else if (r.dim2 != x.dim2 && r.dim1 == x.dim1 && r.dim3 == x.dim3) {  // r: B1SD
407	        OP_LOGD(context, "RotateHalf layout: r B1SD");
408	        tilingData_.set_tilingMode(TILING_MODE_R_B1SD);
409	        tilingData_.set_broadcastFirstDim(x.dim1);
410	        tilingData_.set_broadcastSecondDim(x.dim2);
411	        tilingData_.set_totalSLines(x.dim3);
412	    } else {
413	        tilingData_.set_tilingMode(TILING_MODE_UNKNOWN);
414	    }
415	}
416	
417	inline void RotateHalfTiling::ChooseTilingMode(const gert::Shape &xShape, const gert::Shape &rShape)
418	{
419	    Dim3D xDim {0, 0, 0};
420	    Dim3D rDim {0, 0, 0};
421	    if (isTndLayOut) {
422	        xDim = {1,
423	            static_cast<int64_t>(xShape.GetDim(DIM_FIRST)),
424	            static_cast<int64_t>(xShape.GetDim(DIM_SECOND))};
425	        rDim = {1,
426	            static_cast<int64_t>(rShape.GetDim(DIM_FIRST)),
427	            static_cast<int64_t>(rShape.GetDim(DIM_SECOND))};
428	    } else {
429	        xDim = {static_cast<uint64_t>(xShape.GetDim(DIM_FIRST)),
430	                  static_cast<uint64_t>(xShape.GetDim(DIM_SECOND)),
431	                  static_cast<uint64_t>(xShape.GetDim(DIM_THIRD))};
432	
433	        rDim = {static_cast<uint64_t>(rShape.GetDim(DIM_FIRST)),
434	                  static_cast<uint64_t>(rShape.GetDim(DIM_SECOND)),
435	                  static_cast<uint64_t>(rShape.GetDim(DIM_THIRD))};
436	    }
437	
438	    // Setup indiced-axis sizes
439	    tilingData_.set_axisLenX1(xDim.dim1);
440	    tilingData_.set_axisLenX2(xDim.dim2);
441	    tilingData_.set_axisLenX3(xDim.dim3);
442	    tilingData_.set_axisLenR1(rDim.dim1);
443	    tilingData_.set_axisLenR2(rDim.dim2);
444	    tilingData_.set_axisLenR3(rDim.dim3);
445	
446	    if (rDim.dim1 == xDim.dim1 && rDim.dim2 == xDim.dim2 && rDim.dim3 == xDim.dim3) {
447	        SetTilingModeNoBroadcast(xDim);
448	    } else if (rDim.dim1 == 1 && rDim.dim2 == 1 && rDim.dim3 == 1) {
449	        SetTilingModeBND(xDim);
450	    } else {
451	        SetTilingModeBroadcast(xDim, rDim);
452	    }
453	}
454	
455	inline bool RotateHalfTiling::CalcFullLoadXDTiling(
456	    const ge::DataType &origType, const uint64_t ubSize,
457	    const uint64_t totalS, const uint64_t totalRopeS, const uint64_t isThreeOneDim)
458	{
459	    // Commence RotateHalfRoPEFullLoadXD Tiling
460	    const ge::DataType cmpType = ge::DT_FLOAT;
461	    bool needTypeCast = (origType != cmpType);
462	
463	    uint64_t bytePerOrigData = GetBytePerData(origType);
464	    uint64_t bytePerCmpData = GetBytePerData(cmpType);
465	
466	    // Compute RoPE offset factor under inter-kernel tiling
467	    uint64_t axisX3 = tilingData_.get_axisLenX3();
468	    uint64_t dPadLength = tilingData_.get_dPadLength();
469	
470	    // Init Lr equation params
471	    uint64_t numRopeQueueIn = needTypeCast ? NUM_TWO : NUM_ZERO;
472	    uint64_t numXQueueIn = needTypeCast ? NUM_ONE : NUM_ZERO;
473	    uint64_t numXYBuf = NUM_TWO;  // xBufFp32
474	    uint64_t numRopeTBuf = NUM_TWO;
475	
476	    uint64_t ubTBufSizeFactor = bytePerCmpData * (axisX3 * numXYBuf + numRopeTBuf);
477	    uint64_t ubLoopFactor =
478	        dPadLength * (bytePerOrigData * (axisX3 * numXQueueIn + numRopeQueueIn) + ubTBufSizeFactor);
479	
480	    // Compute tiling factors for RoPE and x
481	    uint64_t ubLoopPerCoreMax = GetDiv(ubSize, ubLoopFactor);  // Lx
482	    if (ubLoopPerCoreMax < NUM_ONE) {  // Guard condition for insufficient ub space
483	        return false;
484	    }
485	
486	    uint64_t formerCoreNum = GetCeilDiv(totalS, ubLoopPerCoreMax);  // total cores used
487	    uint64_t ubLoopPerCore = GetCeilDiv(totalS, formerCoreNum);
488	    uint64_t ubLoopLastCore = totalS - ubLoopPerCore * (formerCoreNum - 1);
489	    if (formerCoreNum <= NUM_TWO && totalS >= MIN_CORE_NUM) {
490	        formerCoreNum = MIN_CORE_NUM;
491	        ubLoopPerCore = GetDiv(totalS, formerCoreNum);
492	        ubLoopLastCore = totalS - ubLoopPerCore * (formerCoreNum - 1);
493	    }
494	
495	    // RoPE tiling factors
496	    uint64_t ropeLoopPerCore = (totalRopeS != NUM_ONE) ? ubLoopPerCore : NUM_ONE;
497	    uint64_t ropeLoopLastCore = (totalRopeS != NUM_ONE) ? ubLoopLastCore : NUM_ONE;
498	
499	    const auto aivNumHalf = coreNum / NUM_TWO;
500	    if (formerCoreNum > aivNumHalf) {
501	        return false;
502	    }
503	
504	    coreNum = formerCoreNum;
505	
506	    // only use tilingdata variables for former cores
507	    tilingData_.set_formerCoreNum(formerCoreNum);
508	    tilingData_.set_formerUbLoop(ubLoopPerCore);
509	    tilingData_.set_formerUbLast(ubLoopLastCore);
510	    tilingData_.set_totalSLines(totalS);
511	    // tailCoreNum: DISABLED here
512	    tilingData_.set_tailUbLoop(ropeLoopPerCore);
513	    tilingData_.set_tailUbLast(ropeLoopLastCore);
514	    tilingData_.set_isThreeOneDim(isThreeOneDim);
515	
516	    // Reassign tilingKey for FullLoadXD path
517	    uint64_t tilingMode = tilingData_.get_tilingMode();
518	    tilingKey = TILING_KEY_SMALL_SHAPE_PREFIX + tilingMode * TILING_MODE_WEIGHT + tilingDtype;
519	    return true;
520	}
521	
522	inline bool RotateHalfTiling::CheckRotHalfFullLoadXDConds(const ge::DataType &origType, const uint64_t ubSize)
523	{
524	    // XY1D: second to last dim of RoPE MUST BE 1
525	    uint64_t axisR3 = tilingData_.get_axisLenR3();
526	    uint64_t dLength = tilingData_.get_dLength();  // Dim
527	
528	    // RotateHalfRoPEFullLoadXD will deterriorate if single-core procession load of input x exceeds saved inter-kernel
529	    // MTE costs of RoPE. Hence the totalS allocated to kernels shall not exceed a certain upper cap.
530	    bool hasRotHalfFLXD = (axisR3 == NUM_ONE && dLength <= DIM_IN_NETWORK_SIXTY_FOUR);
531	
532	    if (hasRotHalfFLXD) {
533	        uint64_t isThreeOneDim = 0;  // Recompute phi_rope on kernel using BroadcastDims.
534	        // Extract broadcastAxes
535	        uint64_t axisR1 = tilingData_.get_axisLenR1();
536	        uint64_t axisR2 = tilingData_.get_axisLenR2();
537	        uint64_t axisX1 = tilingData_.get_axisLenX1();
538	        uint64_t axisX2 = tilingData_.get_axisLenX2();
539	
540	        uint64_t totalS = axisX1 * axisX2;
541	        uint64_t totalRopeS = axisR1 * axisR2;
542	
543	        bool hasSameHeadDims = (axisX1 == axisR1 && axisX2 == axisR2);
544	        bool brcbAxesAligned = (hasSameHeadDims || totalRopeS == NUM_ONE);  // RoPE in XY1D or 111D
545	        if (!brcbAxesAligned) {
546	            return false;
547	        }
548	
549	        if (axisR1 == NUM_ONE && axisR2 == NUM_ONE) {
550	            isThreeOneDim = 1;
551	        }
552	
553	        hasRotHalfFLXD = CalcFullLoadXDTiling(origType, ubSize, totalS, totalRopeS, isThreeOneDim);
554	    }
555	    return hasRotHalfFLXD;
556	}
557	
558	inline void RotateHalfTiling::CalcRotateHalfTiling(const ge::DataType &dtype, const uint64_t ubSize)
559	{
560	    uint64_t bytePerData = GetBytePerData(dtype);
561	
562	    // RotateHalfRoPEFullLoadXD conditions, highest priority overrides regular tilingKeys
563	    bool hasRotHalfFLXD = this->CheckRotHalfFullLoadXDConds(dtype, ubSize);
564	    if (!hasRotHalfFLXD) {
565	        // Tiling steps of regular cut-broadcast templates
566	        GetCoreDataTiling();  // Inter-kernel tiling
567	        GetStoreLines(ubSize, bytePerData, dtype);
568	        GetUbLoopTiling();  // Intra-kernel tiling
569	    }
570	
571	    tilingData_.set_tailAxesFLBoost(hasRotHalfFLXD);
572	}
