574	/* judge D/2 aligned */
575	inline void RotateHalfTiling::GetAlignedInfo(const ge::DataType inputDtype, const uint64_t dLength)
576	{
577	    uint64_t halfDLength = GetDiv(dLength, TWO);
578	    uint64_t bytePerData = GetBytePerData(inputDtype);
579	    uint64_t dataEachBlock = GetDiv(BYTE_OF_BLOCK, bytePerData);
580	    tilingData_.set_dLength(dLength);
581	    tilingData_.set_halfDLength(halfDLength);
582	    if (GetRem(halfDLength, dataEachBlock) == 0) {
583	        tilingData_.set_isAligned(1);
584	        tilingData_.set_halfDPadLength(halfDLength);
585	        tilingData_.set_dPadLength(dLength);
586	    } else {
587	        uint64_t halfDPadLength = GetCeilDiv(halfDLength, dataEachBlock) * dataEachBlock;
588	        tilingData_.set_isAligned(0);
589	        tilingData_.set_halfDPadLength(halfDPadLength);
590	        tilingData_.set_dPadLength(halfDPadLength * TWO);
591	    }
592	}
