594	/* Check input shape */
595	ge::graphStatus RotateHalfTiling::CheckShapeSupport(
596	    const gert::Shape &xShape, const gert::Shape &cosShape, const gert::Shape &sinShape, const uint64_t dLength)
597	{
598	    if (isTndLayOut) {
599	        OP_CHECK_IF(xShape.GetDimNum() != TND_DIM_NUM || cosShape.GetDimNum() != TND_DIM_NUM ||
600	                        sinShape.GetDimNum() != TND_DIM_NUM,
601	            OP_LOGE(context, "the input shape must be 3or4-dimensional."),
602	            return ge::GRAPH_FAILED);
603	    } else {
604	        OP_CHECK_IF(xShape.GetDimNum() != DIM_NUM || cosShape.GetDimNum() != DIM_NUM || sinShape.GetDimNum() != DIM_NUM,
605	            OP_LOGE(context, "the input shape must be 3or4-dimensional."),
606	            return ge::GRAPH_FAILED);
607	    }
608	
609	    OP_CHECK_IF(dLength > D_LENGTH_LIMIT,
610	        OP_LOGE(context, "input last dim (head_dim) should be less than %lu.", D_LENGTH_LIMIT),
611	        return ge::GRAPH_FAILED);
612	    OP_CHECK_IF(GetRem(dLength, TWO) != 0,
613	        OP_LOGE(context, "input last dim (head_dim) must be an even number."),
614	        return ge::GRAPH_FAILED);
615	    OP_CHECK_IF(
616	        cosShape != sinShape, OP_LOGE(context, "cos shape and sin shape should be equal."), return ge::GRAPH_FAILED);
617	    uint64_t cosDLength = static_cast<uint64_t>(cosShape.GetDim(DIM_FOURTH));
618	    if (isTndLayOut) {
619	        cosDLength = static_cast<uint64_t>(cosShape.GetDim(DIM_THIRD));
620	    }
621	    OP_CHECK_IF(cosDLength != dLength,
622	        OP_LOGE(
623	            context, "input last dim (head_dim) should be equal, but get x [%lu] and cos [%lu].", dLength, cosDLength),
624	        return ge::GRAPH_FAILED);
625	    return ge::GRAPH_SUCCESS;
626	}
