628	/* Check stride support */
629	ge::graphStatus RotateHalfTiling::CheckStrideSupport(const ge::DataType inputDtype)
630	{
631	    uint64_t tilingMode = tilingData_.get_tilingMode();
632	    uint64_t stride = 0;
633	    uint64_t bSize = tilingData_.get_broadcastFirstDim();
634	    uint64_t nSize = tilingData_.get_broadcastSecondDim();
635	    uint64_t dLength = tilingData_.get_dLength();
636	    uint64_t bytePerData = GetBytePerData(inputDtype);
637	    if (tilingMode == TILING_MODE_SBND) {
638	        stride = (bSize * nSize - 1) * dLength * bytePerData / BYTE_OF_BLOCK;
639	    } else if (tilingMode == TILING_MODE_BSND) {
640	        stride = (nSize - 1) * dLength * bytePerData / BYTE_OF_BLOCK;
641	    } else {
642	        OP_LOGD(context, "This tilingMode does not require processing");
643	    }
644	    OP_CHECK_IF(stride > UINT16_MAX,
645	        OP_LOGE(context, "DataCopy Stride should be less than [%lu], but get [%lu].", UINT16_MAX, stride),
646	        return ge::GRAPH_FAILED);
647	    return ge::GRAPH_SUCCESS;
648	}
649	
650	/**
651	 * Check do not use Rope:
652	 * 1. layout=BNSD
653	 * 2. if D is aligned: check B * N > 8 * S --> return true
654	 * 3. if D is unaligned: check 2 * B * N > S / coreNum && D < 80 --> return true
655	 * else false
656	 *
657	 * **Note: The above judgment conditions are empirical values obtained through testing**
658	 */
659	inline bool RotateHalfTiling::CheckBnsdBlockSkip()
660	{
661	    if (tilingData_.get_tilingMode() == TILING_MODE_BNSD) {
662	        int64_t broadcastDim = tilingData_.get_broadcastFirstDim() * tilingData_.get_broadcastSecondDim();
663	        int64_t unalignedBroadcastTime = broadcastDim * BNSD_UNALIGNED_BLOCK_BN_SCALE;
664	        int64_t alignedSThreshold = tilingData_.get_totalSLines() * BNSD_ALIGNED_BLOCK_S_SCALE;
665	        int64_t eachCoreSLines = GetCeilDiv(tilingData_.get_totalSLines(), coreNum);
666	
667	        if (tilingData_.get_isAligned() == 1 && broadcastDim > alignedSThreshold) {
668	            return true;
669	        }
670	        if (tilingData_.get_isAligned() == 0 && unalignedBroadcastTime > eachCoreSLines &&
671	            tilingData_.get_dLength() < BNSD_UNALIGNED_BLOCK_D_LENGTH) {
672	            return true;
673	        }
674	    }
675	    return false;
676	}
