678	inline ge::graphStatus RotateHalfTiling::GetInputShapesAndValidate(
679	    gert::Shape &xShape, gert::Shape &cosShape, gert::Shape &sinShape, uint64_t &dLength)
680	{
681	    auto inputXShapePtr = context->GetInputShape(INDEX_INPUT_X);
682	    OP_CHECK_NULL_WITH_CONTEXT(context, inputXShapePtr);
683	    xShape = inputXShapePtr->GetOriginShape();
684	    auto inputCosShapePtr = context->GetInputShape(INDEX_INPUT_COS);
685	    OP_CHECK_NULL_WITH_CONTEXT(context, inputCosShapePtr);
686	    cosShape = inputCosShapePtr->GetOriginShape();
687	    auto inputSinShapePtr = context->GetInputShape(INDEX_INPUT_SIN);
688	    OP_CHECK_NULL_WITH_CONTEXT(context, inputSinShapePtr);
689	    sinShape = inputSinShapePtr->GetOriginShape();
690	
691	    dLength = 0;
692	    uint64_t gmLength = static_cast<uint64_t>(xShape.GetShapeSize());
693	    if (xShape.GetDimNum() == TND_DIM_NUM) {
694	        isTndLayOut = true;
695	        dLength = static_cast<uint64_t>(xShape.GetDim(DIM_THIRD));
696	    } else {
697	        dLength = static_cast<uint64_t>(xShape.GetDim(DIM_FOURTH));
698	    }
699	    tilingData_.set_gmLength(gmLength);
700	
701	    auto shapeCheckRes = CheckShapeSupport(xShape, cosShape, sinShape, dLength);
702	    if (ge::GRAPH_SUCCESS != shapeCheckRes) {
703	        OP_LOGE(context, "input shape does not meet the requirements.");
704	        return shapeCheckRes;
705	    }
706	    return ge::GRAPH_SUCCESS;
707	}
708	
709	inline ge::graphStatus RotateHalfTiling::GetInputDtypeAndValidate(ge::DataType &inputDtype)
710	{
711	    auto inputInfoPtr = context->GetInputDesc(INDEX_INPUT_X);
712	    OP_CHECK_NULL_WITH_CONTEXT(context, inputInfoPtr);
713	    auto cosInfoPtr = context->GetInputDesc(INDEX_INPUT_COS);
714	    OP_CHECK_NULL_WITH_CONTEXT(context, cosInfoPtr);
715	    auto sinInfoPtr = context->GetInputDesc(INDEX_INPUT_SIN);
716	    OP_CHECK_NULL_WITH_CONTEXT(context, sinInfoPtr);
717	    inputDtype = inputInfoPtr->GetDataType();
718	    const ge::DataType cosDtype = cosInfoPtr->GetDataType();
719	    const ge::DataType sinDtype = sinInfoPtr->GetDataType();
720	
721	    OP_CHECK_IF(inputDtype != cosDtype || inputDtype != sinDtype,
722	        OP_LOGE(context, "the dtype of input x, cos and sin must be the same."),
723	        return ge::GRAPH_FAILED);
724	
725	    tilingDtype = GetTilingDtype(inputDtype);
726	    OP_CHECK_IF(tilingDtype == TILING_DTYPE_UNKNOWN,
727	        OP_LOGE(context, "only supports float, float16 and bfloat16 data type."),
728	        return ge::GRAPH_FAILED);
729	    return ge::GRAPH_SUCCESS;
730	}
731	
732	ge::graphStatus RotateHalfTiling::DoRotateHalfTiling()
733	{
734	    // get chip core num and ub size
735	    const auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
736	    const auto aivNum = ascendcPlatform.GetCoreNumAiv();
737	    uint64_t ubSize;
738	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
739	    coreNum = aivNum;
740	
741	    // get x and r shape. layout: [..., head_dim]
742	    gert::Shape xShape;
743	    gert::Shape cosShape;
744	    gert::Shape sinShape;
745	    uint64_t dLength = 0;
746	    auto shapeRes = GetInputShapesAndValidate(xShape, cosShape, sinShape, dLength);
747	    if (ge::GRAPH_SUCCESS != shapeRes) {
748	        return shapeRes;
749	    }
750	
751	    // check input data type
752	    ge::DataType inputDtype;
753	    auto dtypeRes = GetInputDtypeAndValidate(inputDtype);
754	    if (ge::GRAPH_SUCCESS != dtypeRes) {
755	        return dtypeRes;
756	    }
757	
758	    // check D/2 aligned
759	    GetAlignedInfo(inputDtype, dLength);
760	    OP_CHECK_IF(
761	        tilingData_.get_isAligned() == 0 && ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND910,
762	        OP_LOGE(context, "current soc does not support non aligned calculations."),
763	        return ge::GRAPH_FAILED);
764	
765	    OP_CHECK_IF(dLength != 32 && dLength != 64 && dLength != 96 && dLength != 128 &&
766	                    ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND310P,
767	        OP_LOGE(context, "current soc only support d = 32/64/96/128."),
768	        return ge::GRAPH_FAILED);
769	
770	    // Distinguish and mark exact axes and their sizes
771	    ChooseTilingMode(xShape, cosShape);
772	    OP_CHECK_IF(tilingData_.get_tilingMode() == TILING_MODE_UNKNOWN,
773	        OP_LOGE(context, "unknow input layout, unable to calculate."),
774	        return ge::GRAPH_FAILED);
775	
776	    // block some layout=BNSD case, use small operators for higher performance
777	    OP_CHECK_IF(CheckBnsdBlockSkip(),
778	        OP_LOGE(context,
779	            "when input is BNSD layout and  B * N is large or D is not aligned, "
780	            "please do not use RotaryPositionEmbedding fusion operator."),
781	        return ge::GRAPH_FAILED);
782	
783	    tilingKey = GetTilingKey(tilingData_.get_tilingMode(), tilingDtype);
784	
785	    CalcRotateHalfTiling(inputDtype, ubSize);
786	    OP_CHECK_IF(!tilingData_.get_tailAxesFLBoost() && tilingData_.get_storeSLines() <= 0,
787	        OP_LOGE(context, "head_dim shape is too large to compute."),
788	        return ge::GRAPH_FAILED);
789	
790	    if (ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND310P) {
791	        OP_CHECK_IF(ge::GRAPH_SUCCESS != CheckStrideSupport(inputDtype),
792	            OP_LOGE(context, "Stride is too large to compute."),
793	            return ge::GRAPH_FAILED);
794	    }
795	
796	    PrintTilingParams();
797	    return ge::GRAPH_SUCCESS;
798	}
799	
800	ge::graphStatus AiInfraRopeRotateHalfTilingClass::DoOpTiling()
801	{
802	    OP_LOGD(context_->GetNodeName(), "RotateHalf tiling start.");
803	    RotateHalfTiling rotateHalfTiling(context_);
804	
805	    auto tilingRes = rotateHalfTiling.DoRotateHalfTiling();
806	    if (ge::GRAPH_SUCCESS != tilingRes) {
807	        OP_LOGE(context_->GetNodeName(), "DoRotateHalfTiling failed.");
808	        return tilingRes;
809	    }
810	
811	    context_->SetTilingKey(rotateHalfTiling.tilingKey);
812	    context_->SetBlockDim(rotateHalfTiling.coreNum);
813	    rotateHalfTiling.tiling.SaveToBuffer(
814	        context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
815	    context_->GetRawTilingData()->SetDataSize(rotateHalfTiling.tiling.GetDataSize());
816	    const size_t usrWorkspaceSize = 0;
817	    const size_t sysWorkspaceSize = DEFAULT_SYSTEM_WORKSPACESIZE;
818	    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
819	    currentWorkspace[0] = usrWorkspaceSize + sysWorkspaceSize;
820	
821	    OP_LOGD(context_->GetNodeName(), "RotateHalf tiling end.");
822	    return ge::GRAPH_SUCCESS;
823	}
