static __attribute__((always_inline)) inline uint64_t GetCeilDiv(const uint64_t value1, const uint64_t value2)
{
    if (value2 == 0) {
        return value2;
    }
    return (value1 + value2 - 1) / value2;
}

static __attribute__((always_inline)) inline uint64_t GetDiv(const uint64_t value1, const uint64_t value2)
{
    if (value2 == 0) {
        return value2;
    }
    return value1 / value2;
}

static __attribute__((always_inline)) inline uint64_t GetRem(const uint64_t value1, const uint64_t value2)
{
    if (value2 == 0) {
        return value2;
    }
    return value1 % value2;
}

static __attribute__((always_inline)) inline uint64_t GetBytePerData(const ge::DataType &dtype)
{
    if (dtype == ge::DT_FLOAT) {
        return BYTE_PER_DATA_4;
    }
    if (dtype == ge::DT_FLOAT16 || dtype == ge::DT_BF16) {
        return BYTE_PER_DATA_2;
    }
    return BYTE_PER_DATA_4;
}

static __attribute__((always_inline)) inline uint64_t GetTilingDtype(const ge::DataType &dtype)
{
    if (dtype == ge::DT_FLOAT) {
        return TILING_DTYPE_FP32;
    }
    if (dtype == ge::DT_FLOAT16) {
        return TILING_DTYPE_FP16;
    }
    if (dtype == ge::DT_BF16) {
        return TILING_DTYPE_BF16;
    }
    return TILING_DTYPE_UNKNOWN;
}

static __attribute__((always_inline)) inline uint64_t GetTilingKey(
    const uint64_t tilingMode, const uint64_t tilingDtype)
{
    return TILING_KEY_PREFIX + tilingMode * TILING_MODE_WEIGHT + tilingDtype;
}
